import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { it, expect, vi } from "vitest";

// A promise you settle by hand.
function deferred() {
  let resolve, reject;
  const promise = new Promise((res, rej) => { resolve = res; reject = rej; });
  return { promise, resolve, reject };
}

// Success case.
it("shows the course after Load", async () => {
  const api = { getCourse: vi.fn().mockResolvedValue({ title: "CSS Basics" }) };
  render(<CoursePanel api={api} />);
  await userEvent.setup().click(screen.getByRole("button", { name: "Load" }));
  expect(await screen.findByRole("heading", { name: "CSS Basics" })).toBeInTheDocument();
});

// Error, then retry.
it("shows an error and retries", async () => {
  const api = { getCourse: vi.fn()
    .mockRejectedValueOnce(new Error("offline"))
    .mockResolvedValueOnce({ title: "CSS Basics" }) };
  const user = userEvent.setup();
  render(<CoursePanel api={api} />);
  await user.click(screen.getByRole("button", { name: "Load" }));
  await user.click(await screen.findByRole("button", { name: "Try again" }));
  expect(await screen.findByRole("heading", { name: "CSS Basics" })).toBeInTheDocument();
});
```

